import { FC } from 'react';

import styled from 'styled-components';

import { FindInPageModal } from '@openfin/ui-library';

import { Router, withRouter } from '@common/utils/router';

import { useTranslation } from '@common/api/i18next';

import { useFindInPageView } from '@common/hooks/find-in-page/useFindInPageView';

interface Props {
    router: Router;
}

const FindInPageModalView: FC<Props> = ({ router: _router }) => {
    const { t } = useTranslation();
    const {
        currentResultIndex,
        totalResults,
        findText,
        shouldFocusInput,
        resetFocusInput,
        sendClose,
        sendNextResult,
        sendPreviousResult,
        sendFindTextChanged
    } = useFindInPageView();

    return (
        <Container>
            <FindInPageModal
                labels={{
                    ariaLabelSearchField: t('findInPage.ariaLabelSearchField'),
                    placeholder: t('findInPage.placeholder'),
                    titleClose: t('findInPage.titleClose'),
                    titleNextResult: t('findInPage.titleNextResult'),
                    titlePreviousResult: t('findInPage.titlePreviousResult')
                }}
                currentResultIndex={currentResultIndex}
                totalResults={totalResults}
                value={findText}
                shouldFocusInput={shouldFocusInput}
                onResetFocusInput={resetFocusInput}
                onNextResult={sendNextResult}
                onPreviousResult={sendPreviousResult}
                onClose={sendClose}
                onFindTextChanged={sendFindTextChanged}
            />
        </Container>
    );
};

export default withRouter(FindInPageModalView);

const Container = styled.div`
    overflow: hidden;
`;
