import { useCallback, useEffect, useRef, useState } from 'react';

import type OpenFin from '@openfin/core';

import {
    closeFindInPageChannel,
    createFindInPageChannel,
    FindInPageChannelMessagePayload,
    sendFindInPageMessage
} from '../../utils/find-in-page/findInPageChannel';

/**
 * Hook for controlling find in page functionality from the find in page view.
 *
 * @returns Object containing state values and functions to communicate with parent window
 */
export const useFindInPageView = () => {
    const [currentResultIndex, setCurrentResultIndex] = useState<number | null>(null);
    const [totalResults, setTotalResults] = useState<number | null>(null);
    const [findText, setFindText] = useState<string | null>(null);
    const [shouldFocusInput, setShouldFocusInput] = useState(false);

    const channelRef = useRef<BroadcastChannel | null>(null);

    /**
     * Closes the channel used to communicate with the parent window
     */
    const closeChannel = useCallback((): void => {
        if (!channelRef.current) {
            return;
        }
        closeFindInPageChannel(channelRef.current);
        channelRef.current = null;
    }, []);

    /**
     * Sends a message to the parent browser window via BroadcastChannel
     */
    const sendMessageToParent = useCallback((message: FindInPageChannelMessagePayload): void => {
        if (!channelRef.current) {
            console.warn('useFindInPageView: find in page channel not ready');
            return;
        }

        sendFindInPageMessage(channelRef.current, message);
    }, []);

    /**
     * Handles incoming messages from the parent browser window
     */
    const handleMessageFromParent = useCallback(
        (ev: MessageEvent<FindInPageChannelMessagePayload>): void => {
            const { data } = ev;

            switch (data.type) {
                case 'update-state':
                    if (data.currentResultIndex !== undefined) {
                        setCurrentResultIndex(data.currentResultIndex);
                    }
                    if (data.totalResults !== undefined) {
                        setTotalResults(data.totalResults);
                    }
                    if (data.value !== undefined) {
                        setFindText(data.value);
                    }
                    break;

                case 'focus-input':
                    setShouldFocusInput(true);
                    break;

                case 'window-ready':
                    sendMessageToParent({ type: 'view-ready' });
                    break;
            }
        },
        [sendMessageToParent]
    );

    /**
     * Creates a new channel to communicate with the parent window
     */
    const createChannel = useCallback(async (): Promise<void> => {
        channelRef.current = await createFindInPageChannel();
        channelRef.current.onmessage = handleMessageFromParent;
        sendMessageToParent({ type: 'view-ready' });
    }, [handleMessageFromParent, sendMessageToParent]);

    /**
     * Handles the target changed event when the view has been attached to a new content window and creates a new channel for communication with the new parent window
     */
    const handleTargetChanged = useCallback(async (): Promise<void> => {
        closeChannel();
        await createChannel();
    }, [closeChannel, createChannel]);

    /**
     * Notifies parent window that the close button was clicked
     */
    const sendClose = useCallback((): void => {
        sendMessageToParent({ type: 'close' });
    }, [sendMessageToParent]);

    /**
     * Notifies parent window that the next result button was clicked
     */
    const sendNextResult = useCallback((): void => {
        sendMessageToParent({ type: 'next-result' });
    }, [sendMessageToParent]);

    /**
     * Notifies parent window that the previous result button was clicked
     */
    const sendPreviousResult = useCallback((): void => {
        sendMessageToParent({ type: 'previous-result' });
    }, [sendMessageToParent]);

    /**
     * Notifies parent window that the find text has changed
     *
     * @param value - The new find text value
     */
    const sendFindTextChanged = useCallback(
        (value: string): void => {
            setFindText(value);
            sendMessageToParent({ type: 'find-text-changed', value });
        },
        [sendMessageToParent]
    );

    /**
     * Resets the shouldFocusInput flag after the input has been focused
     */
    const resetFocusInput = useCallback((): void => {
        setShouldFocusInput(false);
    }, []);

    useEffect(() => {
        // Focus the view when requested so that the input field is focused
        if (shouldFocusInput) {
            (fin.me as OpenFin.View).focus();
        }
    }, [shouldFocusInput]);

    useEffect(() => {
        // Create the channel to communicate with the parent window and listen for target changed events
        createChannel();
        (fin.me as OpenFin.View).addListener('target-changed', handleTargetChanged);

        return () => {
            (fin.me as OpenFin.View).removeListener('target-changed', handleTargetChanged);
            closeChannel();
        };
    }, [closeChannel, createChannel, handleTargetChanged]);

    return {
        currentResultIndex,
        totalResults,
        findText,
        shouldFocusInput,
        resetFocusInput,
        sendClose,
        sendNextResult,
        sendPreviousResult,
        sendFindTextChanged
    };
};
